def transform(grid):
    """Expand each nonzero cell into a 3x3 block at the zero positions
    of the original 3x3 pattern; leave blocks for zero cells blank."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(3 * w) ] for _ in range(3 * h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                for dr in range(h):
                    for dc in range(w):
                        if grid[dr][dc] == 0:
                            out[r*h + dr][c*w + dc] = color
    return out
